import React, { useState } from 'react';
import {
  StyleSheet,
    Text,
      View,
        TextInput,
          TouchableOpacity,
            FlatList,
              KeyboardAvoidingView,
                Platform,
                } from 'react-native';

                export default function App() {
                  const [task, setTask] = useState('');
                    const [taskList, setTaskList] = useState([]);

                      // Task add karne ka function
                        const handleAddTask = () => {
                            if (task.trim() === '') return;
                                setTaskList([...taskList, { id: Date.now().toString(), text: task, done: false }]);
                                    setTask('');
                                      };

                                        // Task ko complete ya uncomplete toggle karne ka function
                                          const toggleComplete = (id) => {
                                              setTaskList(
                                                    taskList.map((item) =>
                                                            item.id === id ? { ...item, done: !item.done } : item
                                                                  )
                                                                      );
                                                                        };

                                                                          // Task delete karne ka function
                                                                            const deleteTask = (id) => {
                                                                                setTaskList(taskList.filter((item) => item.id !== id));
                                                                                  };

                                                                                    return (
                                                                                        <KeyboardAvoidingView
                                                                                              behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
                                                                                                    style={styles.container}
                                                                                                        >
                                                                                                              <Text style={styles.header}>Meri Todo List 📝</Text>

                                                                                                                    {/* Task Input Box & Add Button */}
                                                                                                                          <View style={styles.inputContainer}>
                                                                                                                                  <TextInput
                                                                                                                                            style={styles.input}
                                                                                                                                                      placeholder="Naya task likhein..."
                                                                                                                                                                placeholderTextColor="#888"
                                                                                                                                                                          value={task}
                                                                                                                                                                                    onChangeText={(text) => setTask(text)}
                                                                                                                                                                                            />
                                                                                                                                                                                                    <TouchableOpacity style={styles.addButton} onPress={handleAddTask}>
                                                                                                                                                                                                              <Text style={styles.addButtonText}>Add</Text>
                                                                                                                                                                                                                      </TouchableOpacity>
                                                                                                                                                                                                                            </View>

                                                                                                                                                                                                                                  {/* Task Items ki List */}
                                                                                                                                                                                                                                        <FlatList
                                                                                                                                                                                                                                                data={taskList}
                                                                                                                                                                                                                                                        keyExtractor={(item) => item.id}
                                                                                                                                                                                                                                                                renderItem={({ item }) => (
                                                                                                                                                                                                                                                                          <View style={styles.taskItem}>
                                                                                                                                                                                                                                                                                      <TouchableOpacity
                                                                                                                                                                                                                                                                                                    style={styles.taskTextContainer}
                                                                                                                                                                                                                                                                                                                  onPress={() => toggleComplete(item.id)}
                                                                                                                                                                                                                                                                                                                              >
                                                                                                                                                                                                                                                                                                                                            <Text style={[styles.taskText, item.done && styles.taskDone]}>
                                                                                                                                                                                                                                                                                                                                                            {item.done ? '✓ ' : '○ '} {item.text}
                                                                                                                                                                                                                                                                                                                                                                          </Text>
                                                                                                                                                                                                                                                                                                                                                                                      </TouchableOpacity>

                                                                                                                                                                                                                                                                                                                                                                                                  <TouchableOpacity
                                                                                                                                                                                                                                                                                                                                                                                                                style={styles.deleteButton}
                                                                                                                                                                                                                                                                                                                                                                                                                              onPress={() => deleteTask(item.id)}
                                                                                                                                                                                                                                                                                                                                                                                                                                          >
                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Text style={styles.deleteText}>✕</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ListEmptyComponent={
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Text style={styles.emptyText}>Koi task nahi hai. Naya add karein!</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </KeyboardAvoidingView>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

